-- PREPARADO; NAO EXECUTADO. SOMENTE LEITURA, projeto ayjppexbzpgdkzbehvzw.
-- Conferir projeto no painel/conexao: current_database()=postgres NAO identifica projeto.
-- Executar arquivo completo apenas em etapa posteriormente autorizada; guardar resultado protegido.
BEGIN ISOLATION LEVEL REPEATABLE READ READ ONLY;
-- Manifesto separado de owners/ACLs, SEM comandos de recomposicao automaticos.
SELECT jsonb_build_object('capturado_em',clock_timestamp(),'database',current_database(),'executor',current_user,'versao',version(),
 'esquemas',(SELECT jsonb_agg(jsonb_build_object('nome',nspname,'owner',pg_get_userbyid(nspowner),'acl',nspacl) ORDER BY nspname) FROM pg_namespace WHERE nspname IN ('financeiro_hml','auth','public','extensions')),
 'objetos',(SELECT jsonb_agg(jsonb_build_object('nome',c.relname,'tipo',c.relkind,'owner',pg_get_userbyid(c.relowner),'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,'acl',c.relacl) ORDER BY c.relname) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='financeiro_hml'),
 'colunas',(SELECT jsonb_agg(jsonb_build_object('tabela',c.relname,'coluna',a.attname,'tipo',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull,'acl',a.attacl,'default',pg_get_expr(d.adbin,d.adrelid)) ORDER BY c.relname,a.attnum) FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace LEFT JOIN pg_attrdef d ON d.adrelid=c.oid AND d.adnum=a.attnum WHERE n.nspname='financeiro_hml' AND c.relkind='r' AND a.attnum>0 AND NOT a.attisdropped),
 'funcoes',(SELECT jsonb_agg(jsonb_build_object('assinatura',format('%I.%I(%s)',n.nspname,p.proname,pg_get_function_identity_arguments(p.oid)),'owner',pg_get_userbyid(p.proowner),'security_definer',p.prosecdef,'config',p.proconfig,'acl',p.proacl,'md5',md5(pg_get_functiondef(p.oid))) ORDER BY p.proname,pg_get_function_identity_arguments(p.oid)) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='financeiro_hml' AND p.prokind IN ('f','p')),
 'politicas',(SELECT jsonb_agg(to_jsonb(p) ORDER BY tablename,policyname) FROM pg_policies p WHERE schemaname='financeiro_hml'),
 'gatilhos',(SELECT jsonb_agg(jsonb_build_object('tabela',c.relname,'nome',t.tgname,'enabled',t.tgenabled,'definicao',pg_get_triggerdef(t.oid)) ORDER BY c.relname,t.tgname) FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='financeiro_hml' AND NOT t.tgisinternal),
 'constraints',(SELECT jsonb_agg(jsonb_build_object('tabela',c.relname,'nome',co.conname,'validada',co.convalidated,'definicao',pg_get_constraintdef(co.oid)) ORDER BY c.relname,co.conname) FROM pg_constraint co JOIN pg_class c ON c.oid=co.conrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='financeiro_hml'),
 'indices',(SELECT jsonb_agg(to_jsonb(i) ORDER BY tablename,indexname) FROM pg_indexes i WHERE schemaname='financeiro_hml'),
 'sequencias',(SELECT jsonb_agg(to_jsonb(s) ORDER BY sequencename) FROM pg_sequences s WHERE schemaname='financeiro_hml'),
 'defaults_acl',(SELECT jsonb_agg(jsonb_build_object('owner',pg_get_userbyid(d.defaclrole),'schema',coalesce(n.nspname,'GLOBAL'),'tipo',d.defaclobjtype,'acl',d.defaclacl) ORDER BY d.defaclrole,d.defaclnamespace,d.defaclobjtype) FROM pg_default_acl d LEFT JOIN pg_namespace n ON n.oid=d.defaclnamespace WHERE n.nspname='financeiro_hml' OR d.defaclnamespace=0),
 'roles',(SELECT jsonb_agg(jsonb_build_object('nome',rolname,'super',rolsuper,'bypass_rls',rolbypassrls,'inherit',rolinherit,'login',rolcanlogin,'create_role',rolcreaterole,'create_db',rolcreatedb) ORDER BY rolname) FROM pg_roles),
 'herancas',(SELECT jsonb_agg(jsonb_build_object('membro',pg_get_userbyid(member),'papel',pg_get_userbyid(roleid),'admin_option',admin_option) ORDER BY member,roleid) FROM pg_auth_members),
 'extensoes',(SELECT jsonb_agg(jsonb_build_object('nome',e.extname,'versao',e.extversion,'schema',n.nspname) ORDER BY e.extname) FROM pg_extension e JOIN pg_namespace n ON n.oid=e.extnamespace)) AS manifesto_catalogo;
-- Precisao: comparar assinaturas, donos e hashes com CATALOGO_BASE_ARQUIVADO.json do V2.2.
SELECT md5((SELECT jsonb_build_object('tabelas',(SELECT jsonb_agg(jsonb_build_object('nome',c.relname,'owner',pg_get_userbyid(c.relowner),'rls',c.relrowsecurity,'force',c.relforcerowsecurity) ORDER BY c.relname) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='financeiro_hml' AND c.relkind='r'), 'gatilhos',(SELECT jsonb_agg(jsonb_build_object('tabela',c.relname,'nome',t.tgname,'enabled',t.tgenabled,'def',pg_get_triggerdef(t.oid)) ORDER BY c.relname,t.tgname) FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='financeiro_hml' AND NOT t.tgisinternal), 'politicas',(SELECT jsonb_agg(to_jsonb(p) ORDER BY tablename,policyname) FROM pg_policies p WHERE schemaname='financeiro_hml'), 'constraints',(SELECT jsonb_agg(jsonb_build_object('tabela',r.relname,'nome',c.conname,'def',pg_get_constraintdef(c.oid)) ORDER BY r.relname,c.conname) FROM pg_constraint c JOIN pg_class r ON r.oid=c.conrelid JOIN pg_namespace n ON n.oid=r.relnamespace WHERE n.nspname='financeiro_hml')))::text) AS estrutura_md5,'d985be75654eb3c1998218115c5d6f06' AS estrutura_esperada_v22;
-- Permissoes efetivas: grants diretos, PUBLIC/heranca e colunas; RLS analisada separadamente.
SELECT r.rolname,c.relname,has_table_privilege(r.oid,c.oid,'SELECT') ler,has_table_privilege(r.oid,c.oid,'INSERT') inserir,has_table_privilege(r.oid,c.oid,'UPDATE') alterar,has_table_privilege(r.oid,c.oid,'DELETE') excluir,has_table_privilege(r.oid,c.oid,'TRUNCATE,REFERENCES,TRIGGER') outras_escritas,has_any_column_privilege(r.oid,c.oid,'INSERT,UPDATE,REFERENCES') escrita_coluna
FROM pg_roles r CROSS JOIN pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE r.rolname IN ('anon','authenticated','service_role') AND n.nspname='financeiro_hml' AND c.relkind='r' ORDER BY r.rolname,c.relname;
SELECT r.rolname,p.oid::regprocedure::text assinatura,has_function_privilege(r.oid,p.oid,'EXECUTE') executar FROM pg_roles r CROSS JOIN pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE r.rolname IN ('anon','authenticated','service_role') AND n.nspname='financeiro_hml' ORDER BY r.rolname,assinatura;
-- ACL expandida inclui concessor, beneficiario e grant option; guardar junto ao manifesto.
SELECT 'schema' tipo,n.nspname objeto,pg_get_userbyid(a.grantor) concessor,CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END beneficiario,a.privilege_type,a.is_grantable FROM pg_namespace n CROSS JOIN LATERAL aclexplode(coalesce(n.nspacl,acldefault('n',n.nspowner))) a WHERE n.nspname='financeiro_hml'
UNION ALL
SELECT 'objeto',format('%I.%I',n.nspname,c.relname),pg_get_userbyid(a.grantor),CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,a.privilege_type,a.is_grantable FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace CROSS JOIN LATERAL aclexplode(coalesce(c.relacl,acldefault(CASE c.relkind WHEN 'S' THEN 's'::"char" ELSE 'r'::"char" END,c.relowner))) a WHERE n.nspname='financeiro_hml' AND c.relkind IN ('r','S','v','m')
UNION ALL
SELECT 'funcao',p.oid::regprocedure::text,pg_get_userbyid(a.grantor),CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,a.privilege_type,a.is_grantable FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a WHERE n.nspname='financeiro_hml';

ROLLBACK;
